    private data class PlayerSource(val url: String, val type: String, val label: String)

    private fun playerSources(raw: String, baseUrl: String): List<PlayerSource> {
        val decoded = raw
            .replace("\\/", "/")
            .replace("\\u0026", "&")
            .replace("&amp;", "&")
            .replace("&#x2F;", "/")
        if (decoded.isBlank()) return emptyList()

        // The current site places its media in JavaScript: sources: [{file, type, label}].
        // Parse each source object without assuming the object is strict JSON (the site
        // also serves JavaScript objects with unquoted property names).
        val sourceArray = Regex("""(?is)\bsources\s*:\s*\[([\s\S]{0,20000}?)\]""")
            .find(decoded)?.groupValues?.get(1) ?: decoded
        val objectPattern = Regex("""(?is)\{([^{}]{1,5000})\}""")
        val filePattern = Regex("""(?is)["']?file["']?\s*:\s*["']([^"']+)["']""")
        val typePattern = Regex("""(?is)["']?(?:type|format)["']?\s*:\s*["']([^"']+)["']""")
        val labelPattern = Regex("""(?is)["']?(?:label|quality|res)["']?\s*:\s*["']([^"']+)["']""")

        return objectPattern.findAll(sourceArray).mapNotNull { match ->
            val item = match.groupValues[1]
            val rawUrl = filePattern.find(item)?.groupValues?.get(1)?.trim()
                ?: return@mapNotNull null
            val url = normalize(rawUrl, baseUrl)
            if (!isValidHttpUrl(url)) return@mapNotNull null

            val type = typePattern.find(item)?.groupValues?.get(1)?.trim()?.lowercase().orEmpty()
            val label = labelPattern.find(item)?.groupValues?.get(1)?.trim().orEmpty()
            PlayerSource(url, type, label.ifBlank { type.uppercase().ifBlank { "Video" } })
        }.distinctBy { it.url }.take(8).toList()
    }

    // Some player servers label a plain HTML/error response as HLS (for example master.txt).
    // Validate extension-less/text HLS candidates before handing them to ExoPlayer, then keep
    // trying other player alternatives instead of stopping at the first unusable URL.
    private suspend fun findValidHlsReferer(
        url: String,
        referers: List<String>,
        userAgent: String,
    ): String? {
        val safeTarget = runCatching {
            URI(url).let { it.host.orEmpty() + it.path.orEmpty() }
        }.getOrDefault("unknown")

        // The provider occasionally rejects the embedded-player referer while accepting
        // the episode page/root referer. Try only these known parent pages; never emit
        // an extension-less source unless the returned body really is an HLS playlist.
        var lastCode = 0
        var lastContentLength = 0
        var lastLookedLikeHtml = false
        var lastContentType = "unknown"
        val orderedReferers = referers.filter { it.isNotBlank() }.distinct().take(3)

        for (referer in orderedReferers) {
            for (attempt in 1..2) {
                val response = runCatching {
                    app.get(
                        url,
                        headers = mapOf(
                            "User-Agent" to userAgent,
                            "Accept" to "application/vnd.apple.mpegurl,application/x-mpegURL,*/*",
                            "Referer" to referer,
                        ),
                        referer = referer,
                        timeout = 6_000L,
                        allowRedirects = true,
                    )
                }.getOrNull()

                lastCode = response?.code ?: 0
                if (response != null && response.isSuccessful) {
                    val body = response.text.trimStart('\uFEFF', ' ', '\t', '\r', '\n')
                    lastContentLength = body.length
                    lastContentType = response.headers["Content-Type"] ?: response.headers["content-type"] ?: "unknown"
                    lastLookedLikeHtml = body.contains("<html", ignoreCase = true) ||
                        body.contains("<!doctype html", ignoreCase = true)
                    if (body.startsWith("#EXTM3U")) return referer
                }

                if (attempt < 2) kotlinx.coroutines.delay(450L)
            }
        }

        Log.w(
            name.uppercase().take(23),
            "HLS candidate rejected after referer variants code=$lastCode contentType=$lastContentType " +
                "chars=$lastContentLength html=$lastLookedLikeHtml target=$safeTarget",
        )
        return null
    }

    private fun isSignedYouTubeMediaUrl(raw: String): Boolean {
        val uri = runCatching { URI(raw) }.getOrNull() ?: return false
        val host = uri.host.orEmpty().lowercase().removePrefix("www.")
        return (host == "googlevideo.com" || host.endsWith(".googlevideo.com")) &&
            uri.rawQuery.orEmpty().split("&").any { it.equals("source=youtube", ignoreCase = true) }
    }

    private fun preferredRefererForMedia(raw: String, fallback: String): String =
        if (isSignedYouTubeMediaUrl(raw)) "https://www.youtube.com/" else fallback

    private fun playerElementSources(document: Document, baseUrl: String): List<PlayerSource> {
        return document.select(
            "video[src], video source[src], source[src], video[data-src], source[data-src], " +
                "[data-hls], [data-file], [data-stream]"
        ).mapNotNull { node ->
            val rawUrl = sequenceOf(
                node.attr("src"),
                node.attr("data-src"),
                node.attr("data-hls"),
                node.attr("data-file"),
                node.attr("data-stream"),
            ).firstOrNull { it.isNotBlank() } ?: return@mapNotNull null
            val url = normalize(rawUrl, baseUrl)
            if (!isValidHttpUrl(url)) return@mapNotNull null

            val declared = (node.attr("type") + " " + node.attr("data-type")).lowercase()
            val urlPath = url.lowercase().substringBefore('?').substringBefore('#')
            val type = when {
                declared.contains("mpegurl") || declared.contains("m3u8") || urlPath.endsWith(".m3u8") -> "hls"
                declared.contains("dash") || declared.contains("mpd") || urlPath.endsWith(".mpd") -> "dash"
                declared.contains("mp4") || urlPath.endsWith(".mp4") || urlPath.endsWith(".m4v") -> "mp4"
                else -> return@mapNotNull null
            }
            val label = sequenceOf(
                node.attr("label"),
                node.attr("data-quality"),
                node.attr("title"),
            ).firstOrNull { it.isNotBlank() }?.trim().orEmpty()
                .ifBlank { type.uppercase() }
            PlayerSource(url, type, label)
        }.distinctBy { it.url }.take(8).toList()
    }

    private fun isYouTubePlaybackFrame(url: String): Boolean {
        val uri = runCatching { URI(url) }.getOrNull() ?: return false
        val host = uri.host.orEmpty().lowercase().removePrefix("www.")
        val path = uri.path.orEmpty().lowercase()
        val isYoutubeHost = host == "youtube.com" ||
            host == "m.youtube.com" ||
            host == "youtu.be" ||
            host == "youtube-nocookie.com" ||
            host.endsWith(".youtube-nocookie.com")
        return isYoutubeHost && (
            path.startsWith("/embed/") ||
            path == "/watch" ||
            path.startsWith("/shorts/") ||
            path.startsWith("/live/")
        )
    }

    private fun siteHost(url: String): String =
        runCatching { URI(url).host.orEmpty().lowercase().removePrefix("www.") }.getOrDefault("")

    private fun isSiteUrl(url: String): Boolean =
        (url.startsWith("http://", true) || url.startsWith("https://", true)) &&
            siteHost(url) == siteHost(mainUrl)

    // Never pass malformed or hostless URLs to CloudStream's player.
    private fun isValidHttpUrl(raw: String): Boolean {
        val uri = runCatching { URI(raw.trim()) }.getOrNull() ?: return false
        val scheme = uri.scheme?.lowercase() ?: return false
        return (scheme == "http" || scheme == "https") && !uri.host.isNullOrBlank()
    }

    private fun normalize(raw: String, base: String = mainUrl): String {
        val cleaned = neonCleanText(raw).orEmpty()
        // Some player scripts omit the scheme. Treat www.host/path as an absolute URL,
        // not as a child path of /vid/ply/; the latter creates redirect loops.
        val absoluteLike = if (Regex("""(?i)^www\.[a-z0-9.-]+(?::\d+)?(?:/|[?#]|$)""").containsMatchIn(cleaned)) {
            "https://$cleaned"
        } else {
            cleaned
        }
        val normalized = neonNormalizeUrl(absoluteLike, base)
        // Some catalog cards still expose legacy /dizi/<episode-slug> links.
        // Current episode pages use /<episode-slug>; rewrite only episode-shaped
        // URLs so real series pages such as /dizi/<show>-son-bolum-izle remain intact.
        return normalized.replace(
            Regex("""(?i)^(https?://(?:www\.)?tvdiziler\.tv)/dizi/(?=[^/?#]*\d+-bolum-izle(?:[-/?#]|$))"""),
            "$1/"
        )
    }

    private fun isEpisodeLike(value: String): Boolean =
        Regex("""(?i)(?:b[öo]l[üu]m|episodes?|ep[\s._-]*\d|s\d{1,2}e\d{1,3}|\d{1,2}\s*[x×]\s*\d{1,3})""")
            .containsMatchIn(value)

    private fun normalizedFilterText(value: String): String =
        value.lowercase()
            .replace("ı", "i")
            .replace("ş", "s")
            .replace("ğ", "g")
            .replace("ü", "u")
            .replace("ö", "o")
            .replace("ç", "c")
            .replace(Regex("""[^a-z0-9]+"""), " ")
            .trim()

